      regra: { min: 2, total: 3 }, janela: 'Sem janela', ficha: 'nao_iniciada',
      plataforma: { resposta: 'Sim (pré-preenchido)', nota: 'Veio do Raio-X, em que a resposta de Impacto na comunidade foi aceita.' },
